<?php
require_once __DIR__.'/../app/application.php';
requirePermission('contract.view');
$id=(int)($_GET['id']??0);$lang=validateChoice($_GET['lang']??'',supportedLanguages(),'en');
$detail=null;try{$detail=contractScopedDetail($id);}catch(Throwable$exception){}
if(!$detail||$detail['contract']['status']==='draft'){http_response_code(404);exit(t('validation.contract_not_found'));}
$contract=$detail['contract'];
$version=dbFetchOne(
    'SELECT * FROM contract_versions WHERE contract_id=:contract AND agency_id=:agency AND version_number=:version AND language_code=:language',
    ['contract'=>$id,'agency'=>$contract['agency_id'],'version'=>$contract['current_version'],'language'=>$lang]
);
if(!$version){http_response_code(404);exit(t('validation.contract_version_not_found'));}
$data=json_decode($version['snapshot_json'],true)?:[];
?><!doctype html><html lang="<?=e($lang)?>" dir="<?=$lang==='ar'?'rtl':'ltr'?>"><head><meta charset="utf-8"><title><?=e($contract['contract_number'])?></title><style>body{font:14px Arial;max-width:900px;margin:30px auto;color:#172536}header{display:flex;justify-content:space-between;border-bottom:3px solid #143b61;padding-bottom:20px}h1{color:#143b61}section{margin:25px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.box{border:1px solid #ccd7e0;padding:15px}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:50px;margin-top:70px}.signature{border-top:1px solid #333;padding-top:8px}@media print{button{display:none}body{margin:0}}</style></head><body><button onclick="window.print()"><?=e(translateInLanguage('common.print_pdf',$lang))?></button><header><div><h1><?=e(translateInLanguage('print.rental_contract',$lang))?></h1><strong><?=e(appConfig('name'))?></strong></div><div><strong><?=e($contract['contract_number'])?></strong><br><?=e(translateInLanguage('field.version',$lang))?> <?=e($version['version_number'])?><br><?=e(translateInLanguage('status.'.$contract['status'],$lang))?></div></header><section class="grid"><div class="box"><h2><?=e(translateInLanguage('field.customer',$lang))?></h2><p><?=e($data['customer']['name']??'')?></p><p><?=e(translateInLanguage('field.identity',$lang))?>: <?=e($data['customer']['identity_number']??'')?></p><p><?=e(translateInLanguage('field.licence',$lang))?>: <?=e($data['customer']['licence_number']??'')?></p></div><div class="box"><h2><?=e(translateInLanguage('field.vehicle',$lang))?></h2><p><?=e($data['vehicle']['description']??'')?></p><p><?=e(translateInLanguage('field.registration',$lang))?>: <?=e($data['vehicle']['registration_number']??'')?></p><p>VIN: <?=e($data['vehicle']['vin']??'')?></p></div></section><section class="box"><h2><?=e(translateInLanguage('section.rental_summary',$lang))?></h2><p><?=e(translateInLanguage('field.pickup',$lang))?>: <?=e($data['period']['pickup_at']??'')?></p><p><?=e(translateInLanguage('field.return',$lang))?>: <?=e($data['period']['return_at']??'')?></p><p><?=e(translateInLanguage('field.total',$lang))?>: <?=localizedMoney($data['pricing']['total']??0,$data['currency']??'MAD',$lang)?></p><p><?=e(translateInLanguage('field.deposit',$lang))?>: <?=localizedMoney($data['deposit_amount']??0,$data['currency']??'MAD',$lang)?></p></section><section><h2><?=e(translateInLanguage('print.terms',$lang))?></h2><p><?=nl2br(e($version['terms_text']))?></p></section><div class="signatures"><div class="signature"><?=e(translateInLanguage('print.customer_signature',$lang))?></div><div class="signature"><?=e(translateInLanguage('print.agency_signature',$lang))?></div></div></body></html>
